package methodLabQuestion;

public class Question6 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		printSquare();
	}
	public static void printSquare()
	{ int x=1;
		for(int i=1;i<=5;i++)
		{
			long l= (long)Math.pow(x,2); // 
			 System.out.println(l);
			 x++;
		}
	}

}
